def norm_sg03(rows):
    from collections import OrderedDict
    from operator import itemgetter

    def preprocess(row):
        return row.strip().lower()

    unique_rows = OrderedDict()
    for row in rows:
        key = preprocess(row)
        if key not in unique_rows:
            unique_rows[key] = row

    processed_rows = [">" + row[:6] for row in unique_rows.values()]
    processed_rows.sort(key=itemgetter(1, 0))

    return processed_rows
