def norm_sg05(rows):
    def preprocess(row):
        row = row.strip()
        row = row[:9]
        return row.lower()

    seen = {}
    result = []
    for row in rows:
        key = preprocess(row)
        if key not in seen:
            seen[key] = row
            result.append(row)

    result = sorted(result, key=lambda x: (-len(x), x))
    return ['·' + row for row in result]
